import{_ as o,o as d,c as t,a2 as a}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"検索構文","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/search-syntax.md","filePath":"ja-JP/user-guide/search-syntax.md","lastUpdated":1785993908000}'),c={name:"ja-JP/user-guide/search-syntax.md"};function s(r,e,n,i,l,p){return d(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="検索構文" tabindex="-1">検索構文 <a class="header-anchor" href="#検索構文" aria-label="Permalink to &quot;検索構文&quot;">​</a></h1><p>Lertaro のクエリボックスは、単純な入力以上のことに対応しています。以下の演算子はすべて、同じクエリの中で通常のあいまい検索語と組み合わせて使えます。</p><h2 id="あいまい検索-既定" tabindex="-1">あいまい検索 (既定) <a class="header-anchor" href="#あいまい検索-既定" aria-label="Permalink to &quot;あいまい検索 (既定)&quot;">​</a></h2><p>名前の一部を入力すると、その文字がファイル/フォルダー名のどこかに順番どおりに出現する限り、Lertaro はそれを見つけます。連続した部分文字列を入力する必要はありません:</p><table tabindex="0"><thead><tr><th>入力</th><th>一致する例</th></tr></thead><tbody><tr><td><code>swlst</code></td><td><code>Lertaro.exe</code></td></tr><tr><td><code>report</code></td><td><code>Q3-report-final.docx</code></td></tr></tbody></table><p><strong>設定 → 一般 → システム → あいまい一致を有効化</strong> でこの設定をオフにすると、演算子の付いていない通常の検索語は連続した部分文字列として現れる必要があります — <code>abc</code> は <code>a-b-c</code> に一致しなくなります。以下の表にある演算子はすべて、この設定の状態に関わらず同じように動作します。この設定が変えるのは通常の検索語に対する要件だけです。<code>&#39;</code> 演算子はこの設定の状態に関わらず、その語 1 つだけ厳密さを反転させるため、あいまい一致の語を厳密なクエリの中に混ぜたり、逆にあいまいなクエリの中に厳密な語を混ぜたりするのに使えます。設定自体を変更する必要はありません。</p><h2 id="複数の単語" tabindex="-1">複数の単語 <a class="header-anchor" href="#複数の単語" aria-label="Permalink to &quot;複数の単語&quot;">​</a></h2><p>単語をスペースで区切ります。各単語は検索結果をさらに絞り込みますが、入力した順序どおりに単語が並んでいる必要は <strong>ありません</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>report final</span></span></code></pre></div><p>は <code>Q3-report-final.docx</code> と同様に <code>final-Q3-report.docx</code> にも一致します。</p><h2 id="大文字・小文字の区別" tabindex="-1">大文字・小文字の区別 <a class="header-anchor" href="#大文字・小文字の区別" aria-label="Permalink to &quot;大文字・小文字の区別&quot;">​</a></h2><ul><li><strong>すべて小文字</strong> のクエリは大文字・小文字を区別しません: <code>myfile</code> は <code>MyFile</code>、<code>MYFILE</code> などに一致します。</li><li><strong>大文字を含む</strong> クエリは、その語について大文字・小文字を区別するようになります: <code>MyFile</code> は <code>MyFile</code> にのみ一致し、<code>myfile</code> には一致しません。</li></ul><h2 id="演算子" tabindex="-1">演算子 <a class="header-anchor" href="#演算子" aria-label="Permalink to &quot;演算子&quot;">​</a></h2><table tabindex="0"><thead><tr><th>接頭辞/接尾辞</th><th>例</th><th>効果</th></tr></thead><tbody><tr><td><em>(なし)</em></td><td><code>report</code></td><td>名前のどこかにあいまい一致 (既定)。</td></tr><tr><td><code>!</code></td><td><code>!temp</code></td><td>名前に <code>temp</code> という完全な部分文字列を含む結果を <strong>除外</strong> します (これはあいまい一致ではありません)。</td></tr><tr><td><code>&#39;</code></td><td><code>&#39;report</code></td><td>この語 1 つだけ <strong>厳密さを反転</strong> させます — あいまい一致が有効(既定)なら完全な部分文字列一致に、設定であいまい一致を無効にしている場合はこの語だけあいまい一致に戻ります。</td></tr><tr><td><code>&#39;...&#39;</code></td><td><code>&#39;final report&#39;</code></td><td>単語境界にアンカーされた完全一致 (より大きな単語の内部には一致しません)。</td></tr><tr><td><code>^</code></td><td><code>^IMG</code></td><td><strong>前方一致</strong> — 名前が <code>IMG</code> で始まる必要があります。</td></tr><tr><td><code>$</code></td><td><code>.pdf$</code></td><td><strong>後方一致</strong> — 名前が <code>.pdf</code> で終わる必要があります。</td></tr><tr><td><code>^...$</code></td><td><code>^readme.md$</code></td><td><strong>完全一致</strong> — 名前が <code>readme.md</code> とまったく同一である必要があります。両方が<strong>同じ</strong>単語を挟んでいる場合のみです。別々の単語に付いている場合は、それぞれ独立した前方一致と後方一致のままです。</td></tr><tr><td><code>|</code></td><td><code>report | summary</code></td><td><strong>OR</strong> — パイプのどちらか一方に一致します。</td></tr></tbody></table><p>これらは自由に組み合わせられます。例えば <code>^IMG !.png$ 2024</code> は、<code>IMG</code> で始まり、2024 年のもので、かつ PNG では <em>ない</em> ファイルを見つけます。</p><p>OR クエリでは、ある検索結果に実際に一致したすべての語が、最初に一致した語だけでなく、その名前の中でハイライトされます。そのため <code>report | summary</code> は、両方の単語を含む検索結果ではその両方がハイライトされます。</p><h2 id="複数行の貼り付け" tabindex="-1">複数行の貼り付け <a class="header-anchor" href="#複数行の貼り付け" aria-label="Permalink to &quot;複数行の貼り付け&quot;">​</a></h2><p>複数行を含むテキスト (例えば、スプレッドシートやテキストファイルから 1 行ずつコピーしたファイル名) を貼り付けると、Lertaro はそれをそのまま貼り付けるのではなく、自動的に OR クエリに変換します:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>123</span></span>
<span class="line"><span>456</span></span>
<span class="line"><span>678</span></span></code></pre></div><p>は <code>123 | 456 | 678</code> として貼り付けられ、3 つのいずれかに一致します。空行はスキップされます。通常の 1 行のみの貼り付けには影響しません。</p><h2 id="ドライブを指定する" tabindex="-1">ドライブを指定する <a class="header-anchor" href="#ドライブを指定する" aria-label="Permalink to &quot;ドライブを指定する&quot;">​</a></h2><p>クエリの先頭にドライブレターとコロンを付けると、そのドライブに検索結果を限定できます。その後は通常どおり検索語を続けて入力します:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>d: report</span></span></code></pre></div><p>は <code>D:</code> ドライブのみを検索します。</p><p>スペースは省略できます。<code>d:report</code> は <code>d: report</code> と同じ意味です。</p><h2 id="パスモード" tabindex="-1">パスモード <a class="header-anchor" href="#パスモード" aria-label="Permalink to &quot;パスモード&quot;">​</a></h2><p>クエリにパス区切り文字 (<code>\\</code> または <code>/</code>) が含まれている場合、Lertaro はパスモードに切り替わり、名前だけでなくフルパスに対して一致を行います。既知のフォルダーへ直接ジャンプしたいときに便利です:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>D:\\Projects\\Lertaro</span></span></code></pre></div><p>末尾に区切り文字を付けた場合 (<code>D:\\Projects\\</code>) は、そのフォルダー自体の <em>中身</em> を検索します。</p><h2 id="フォルダー名とワイルドカードでの二次絞り込み-query-tokens" tabindex="-1">フォルダー名とワイルドカードでの二次絞り込み (Query Tokens) <a class="header-anchor" href="#フォルダー名とワイルドカードでの二次絞り込み-query-tokens" aria-label="Permalink to &quot;フォルダー名とワイルドカードでの二次絞り込み (Query Tokens)&quot;">​</a></h2><p>Lertaro では、メイン検索キーワードの後にクエリトークン（既定では <code>:</code> プレフィックス、または各機能専用のプレフィックスを使用）をチェーンさせることで、検索結果を二次絞り込みできます。</p><ul><li><strong>ワイルドカード二次フィルター (<code>:?&lt;ワイルドカード表現&gt;</code> または <code>?&lt;ワイルドカード表現&gt;</code>)</strong>: Windows 標準のワイルドカード構文（<code>?</code> は任意の 1 文字、<code>*</code> は任意の 0 文字以上）を使用して結果を絞り込みます。たとえば <code>mp4 :?(2026???????????)</code> または <code>mp4 ?(2026???????????)</code> と入力すると、2026 年および 11 桁のタイムスタンプが含まれる重複ファイルを正確に絞り込めます。<code>|</code> や <code>;</code> で区切って複数の条件を OR 指定することも可能です（例: <code>?(2026*)|*.png</code>）。</li><li><strong>パスフィルター (<code>::&lt;パス表現&gt;</code>)</strong>: 検索結果名または親フォルダー名が指定したテキストに一致することを要求します（例: <code>1080 ::wallpapers</code> や <code>report ::2024</code>）。</li><li><strong>カスタムカテゴリフィルター (<code>:@&lt;キーワード&gt;</code>)</strong>: 事前設定された拡張子やカテゴリのルールを適用します（例: <code>:@doc</code> や <code>:@video</code>）。</li></ul><h2 id="語がファイルではなくフォルダーを表している場合" tabindex="-1">語がファイルではなくフォルダーを表している場合 <a class="header-anchor" href="#語がファイルではなくフォルダーを表している場合" aria-label="Permalink to &quot;語がファイルではなくフォルダーを表している場合&quot;">​</a></h2><p>ファイル/フォルダー名だけでは結果が埋まらなかった場合、Lertaro は自動的にそれを補い、語が祖先フォルダーにも一致できるようにします——特別な構文は不要です:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>d01j dcj</span></span></code></pre></div><p>は、<code>dcj</code> がそのファイル自身の名前には一切現れなくても、<code>d01j</code> という名前のファイルが <code>dcj</code> という名前(またはそれにエイリアスされた名前)のフォルダーの中にあれば見つけます。これは、ファイル自身の名前でカバーされなかった部分を、そのファイルより上にあるフォルダーの名前で補うだけの仕組みです——少なくとも 1 つの語はファイル名自体に一致する必要があり、通常の名前だけの検索がページを埋めきらなかった場合にのみ発動します。見つかったものはそれらの結果に混ぜられるのではなく後ろに追加されるため、通常の検索がすでに見つけているはずの結果を押しのけたり順序を変えたりすることは決してありません。祖先フォルダーはファイル名とまったく同じ方法で照合されるため、ピンインもここで中国語のフォルダー名に届きます。</p><h2 id="_1-回の検索だけ除外ルールを無視する" tabindex="-1">1 回の検索だけ除外ルールを無視する <a class="header-anchor" href="#_1-回の検索だけ除外ルールを無視する" aria-label="Permalink to &quot;1 回の検索だけ除外ルールを無視する&quot;">​</a></h2><p>クエリの先頭に <code>*</code> を付けると、設定を変更することなく、その検索に限り自分の<a href="./settings/index-drives.html#除外ルール">除外ルール</a> (<code>ExcludedPaths</code>、無視されるグロブパターン、無視される正規表現) を無視して検索します:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>*node_modules</span></span></code></pre></div><p><code>*</code> 自体はマッチングの前に取り除かれるため、検索テキストの一部として扱われることはありません。これはすでにインデックス化済みの検索結果を表示するだけです。そもそも一度もインデックス化されなかったフォルダー (ネットワークドライブや WSL ドライブ上の除外フォルダーなど) は、それでも表示されません。隠しファイル/システムファイルはいずれの場合もフィルタリングされたままです — これが影響するのは、あくまで自分自身の除外ルール設定だけです。何も続けずに <code>*</code> だけを入力した時点では、まだ検索が実際に実行されていないため、「検索結果がありません」ではなく「入力を続けて検索してください」というプロンプトが表示されます。</p><h2 id="検索結果種別トリガー" tabindex="-1">検索結果種別トリガー <a class="header-anchor" href="#検索結果種別トリガー" aria-label="Permalink to &quot;検索結果種別トリガー&quot;">​</a></h2><p>任意機能で、既定ではオフになっています — 文字は自分で割り当てます。<strong>設定 → 一般 → クイック検索ウィンドウ → 検索結果種別の優先度</strong> で、ある検索結果種別にトリガー文字を割り当てている場合、クイックウィンドウでその文字を一番最初に入力すると、その種別の検索結果のみ — アプリケーション、設定、特定の 1 つのファイルフィルター、あるプラグイン独自の項目、あるいは単純なファイル — が表示され、他のすべての種別は非表示になります:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>;vs</span></span></code></pre></div><p>は、<code>;</code> がその種別に設定されたトリガーであれば、他の種別のテキストがどれだけよく一致していたとしても、アプリケーションの中からのみ「Visual Studio」を見つけます。トリガー文字だけを入力してその後に何も続けていない時点では、「検索結果がありません」の代わりに、その種別名を示すプロンプトが表示されます。履歴とお気に入りは、トリガーの有無に関わらず影響を受けず、常に最初に表示されます。既定ではトリガーは設定されていません。設定方法は<a href="./settings/general.html#クイック検索ウィンドウ">一般設定</a>を参照してください。</p><h2 id="中国語ファイル名-ピンインエイリアス" tabindex="-1">中国語ファイル名: ピンインエイリアス <a class="header-anchor" href="#中国語ファイル名-ピンインエイリアス" aria-label="Permalink to &quot;中国語ファイル名: ピンインエイリアス&quot;">​</a></h2><p>中国語の文字を含むファイル名は、特別な設定なしに、自動的にピンインで検索可能になります:</p><ul><li><strong>フルピンイン</strong>: <code>chongqing</code> と入力すると <code>重庆</code> というファイルに一致します。</li><li><strong>頭文字</strong>: <code>cq</code> と入力しても <code>重庆</code> に一致します (各音節の最初の文字)。</li><li><strong>多音字</strong> (複数の正しい発音を持つ文字) は、よく使われる読み方それぞれに対してエイリアスを生成するため、どの発音を思い浮かべても一致しやすくなっています。</li></ul><p>これは同梱のエイリアスプラグインによって処理されています — 有効になっているか確認したい場合は <strong>設定 → プラグイン</strong> を参照してください。</p><h2 id="スペイン語ファイル名-アクセント-エイリアス" tabindex="-1">スペイン語ファイル名: アクセント エイリアス <a class="header-anchor" href="#スペイン語ファイル名-アクセント-エイリアス" aria-label="Permalink to &quot;スペイン語ファイル名: アクセント エイリアス&quot;">​</a></h2><p>スペイン語のアクセント文字 (<code>á</code>, <code>é</code>, <code>í</code>, <code>ó</code>, <code>ú</code>, <code>ü</code>, <code>ñ</code>) を含むファイル名は、特別の設定なしでアクセントなしの標準 ASCII 文字で自動的に検索できます。<code>cancion</code> と入力すると <code>Canción.mp3</code> に、<code>nino</code> と入力すると <code>Niño.txt</code> に、<code>ciguena</code> と入力すると <code>Cigüeña.png</code> に一致します。一致した文字（元のファイル名のアクセント文字を含む）は正確にハイライト表示されます。この機能は付属の <code>SpanishAlias</code> プラグインによって提供されます（<strong>設定 → プラグイン</strong> で有効化状態を確認できます）。</p><h2 id="お気に入り、カスタムエイリアスではない" tabindex="-1">お気に入り、カスタムエイリアスではない <a class="header-anchor" href="#お気に入り、カスタムエイリアスではない" aria-label="Permalink to &quot;お気に入り、カスタムエイリアスではない&quot;">​</a></h2><p>Lertaro には、汎用的な「自分でエイリアス/マクロを定義する」仕組みはありません。それに最も近いのが <a href="./settings/favorites.html">お気に入り</a> です。フォルダー・ファイル・URL を独自の表示名でピン留めすると、その名前で検索できるようになります (検索結果には ★ マーク付きで表示されます)。プログラムを起動する独自のキーワードが欲しい場合は、代わりに<a href="./instant-answers.html#カスタムコマンド">カスタムコマンド</a>を参照してください。</p>`,52)])])}const u=o(c,[["render",s]]);export{g as __pageData,u as default};
